// One-time cleanup for the Spec/Communication Protocol trunk-staleness rework: deletes
// the old CO-keyed `repo_documents` rows (doc_type='spec_communication_protocol',
// co_number != '') left over from when this doc was generated per-branch/per-CO. Going
// forward there is exactly one Spec CP row per repo (co_number='', regenerated by
// worker.js's spec-doc job queue) - these rows are superseded, not just stale, so they
// are deleted rather than left as dead data.
//
// Not run automatically as part of the schema migration - run by hand when ready:
//   node scripts/purge-legacy-spec-docs.js   (or `make purge-legacy-spec-docs`)

require('dotenv').config();

const db = require('../app/lib/db');

async function main() {
  const result = await db.query(`DELETE FROM repo_documents WHERE doc_type = 'spec_communication_protocol' AND co_number != ''`);
  console.log(`Deleted ${result.affectedRows} legacy CO-keyed Spec/Communication Protocol row(s).`);
}

main()
  .then(() => process.exit(0))
  .catch((err) => {
    console.error('Purge legacy spec docs failed:', err.message);
    process.exit(1);
  });
